mapper.select:
SELECT a.`id` `id`, a.`record_id` `recordId`, a.`red` `red`, a.`green` `green`, a.`yellow` `yellow`, b.`code` `deviceCode`, b.`area_name` `areaName`, a.`data_time` `dataTime` FROM `traffic_light` a LEFT JOIN `security_device` b ON a.`device_id` = b.`third_party_id`
and a.`data_time` >= #{param.period.begin}
and a.`data_time` <= #{param.period.end}
